package com.brittech.minibuddy;
import android.content.*;
import android.database.Cursor;
import android.database.sqlite.*;
import org.json.*;
import java.util.*;
/** Each APK has a private database. Every educational record is additionally scoped by profile. */
public final class EducationDb extends SQLiteOpenHelper {
 public EducationDb(Context c){super(c,"education.db",null,1);}
 public void onCreate(SQLiteDatabase d){
  d.execSQL("CREATE TABLE profiles(id TEXT PRIMARY KEY,name TEXT NOT NULL)");d.execSQL("INSERT INTO profiles VALUES('default','Estudante')");
  d.execSQL("CREATE TABLE attempts(id INTEGER PRIMARY KEY,profile TEXT,qid TEXT,skill TEXT,context TEXT,action INTEGER,prob REAL,policy TEXT,correct INTEGER,assisted INTEGER,created INTEGER,reviewed INTEGER DEFAULT 0,review_correct INTEGER,review_time INTEGER)");
  d.execSQL("CREATE TABLE strategies(profile TEXT,context TEXT,action INTEGER,n INTEGER,total REAL,PRIMARY KEY(profile,context,action))");
  d.execSQL("CREATE TABLE knowledge(id INTEGER PRIMARY KEY,profile TEXT,question TEXT,text TEXT,status TEXT,created INTEGER,updated INTEGER)");
  d.execSQL("CREATE TABLE revisions(id INTEGER PRIMARY KEY,knowledge_id INTEGER,profile TEXT,text TEXT,status TEXT,created INTEGER)");
  d.execSQL("CREATE TABLE rewards(profile TEXT,mission TEXT,xp INTEGER,PRIMARY KEY(profile,mission))");
 }
 public void onUpgrade(SQLiteDatabase d,int a,int b){throw new IllegalStateException("Migração necessária");}
 public synchronized String profile(Context c){return c.getSharedPreferences("education",0).getString("profile","default");}
 public synchronized LinkedHashMap<String,String> profiles(){LinkedHashMap<String,String> map=new LinkedHashMap<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT id,name FROM profiles ORDER BY rowid",null)){while(c.moveToNext())map.put(c.getString(0),c.getString(1));}return map;}
 public synchronized String addProfile(String name){if(name.trim().isEmpty()||name.length()>80)throw new IllegalArgumentException("Nome de 1 a 80 caracteres");String id=UUID.randomUUID().toString();ContentValues v=new ContentValues();v.put("id",id);v.put("name",name.trim());getWritableDatabase().insertOrThrow("profiles",null,v);return id;}
 private long count(String sql,String...args){try(Cursor c=getReadableDatabase().rawQuery(sql,args)){return c.moveToFirst()?c.getLong(0):0;}}
 public String context(String p,String skill){long errors=count("SELECT COUNT(*) FROM attempts WHERE profile=? AND skill=? AND correct=0",p,skill);return skill+"|"+(errors>0?"revisar":"iniciar");}
 public PedagogyPolicy.Choice choose(String p,String context,String mode){int[] n=new int[4];double[] t=new double[4];try(Cursor c=getReadableDatabase().rawQuery("SELECT action,n,total FROM strategies WHERE profile=? AND context=?",new String[]{p,context})){while(c.moveToNext()){int a=c.getInt(0);n[a]=c.getInt(1);t[a]=c.getDouble(2);}}return PedagogyPolicy.choose(n,t,mode,new Random());}
 public synchronized long attempt(String p,JSONObject q,String ctx,PedagogyPolicy.Choice choice,String mode,boolean correct,boolean assisted){ContentValues v=new ContentValues();v.put("profile",p);v.put("qid",q.optString("id"));v.put("skill",q.optString("skill"));v.put("context",ctx);v.put("action",choice.action);v.put("prob",choice.probability);v.put("policy",mode);v.put("correct",correct?1:0);v.put("assisted",assisted?1:0);v.put("created",System.currentTimeMillis());return getWritableDatabase().insertOrThrow("attempts",null,v);}
 public synchronized JSONObject due(String p){try(Cursor c=getReadableDatabase().rawQuery("SELECT id,qid,created FROM attempts WHERE profile=? AND reviewed=0 AND created<=? ORDER BY id LIMIT 1",new String[]{p,Long.toString(System.currentTimeMillis()-30*60*1000)})){if(!c.moveToFirst())return null;try{return new JSONObject().put("id",c.getLong(0)).put("qid",c.getString(1));}catch(JSONException e){throw new IllegalStateException(e);}}}
 public synchronized boolean review(String p,long id,boolean correct){SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{
  String ctx,mode;int action,assisted;try(Cursor c=d.rawQuery("SELECT context,action,policy,assisted FROM attempts WHERE profile=? AND id=? AND reviewed=0 AND created<=?",new String[]{p,Long.toString(id),Long.toString(System.currentTimeMillis()-1800000)})){if(!c.moveToFirst())return false;ctx=c.getString(0);action=c.getInt(1);mode=c.getString(2);assisted=c.getInt(3);}
  d.execSQL("UPDATE attempts SET reviewed=1,review_correct=?,review_time=? WHERE profile=? AND id=?",new Object[]{correct?1:0,System.currentTimeMillis(),p,id});
  if("adaptativo".equals(mode)&&assisted==1){d.execSQL("INSERT OR IGNORE INTO strategies VALUES(?,?,?,0,0)",new Object[]{p,ctx,action});d.execSQL("UPDATE strategies SET n=n+1,total=total+? WHERE profile=? AND context=? AND action=?",new Object[]{correct?1:-1,p,ctx,action});}
  d.setTransactionSuccessful();return true;
 }finally{d.endTransaction();}}
 public synchronized long teach(String p,String question,String text){validate(text);long now=System.currentTimeMillis();ContentValues v=new ContentValues();v.put("profile",p);v.put("question",question);v.put("text",text.trim());v.put("status","pendente");v.put("created",now);v.put("updated",now);long id=getWritableDatabase().insertOrThrow("knowledge",null,v);revision(p,id,text,"pendente");return id;}
 private void validate(String t){if(t.trim().length()<20||t.length()>10000)throw new IllegalArgumentException("Explique com pelo menos 20 e no máximo 10.000 caracteres.");}
 private void revision(String p,long id,String text,String status){ContentValues v=new ContentValues();v.put("knowledge_id",id);v.put("profile",p);v.put("text",text);v.put("status",status);v.put("created",System.currentTimeMillis());getWritableDatabase().insertOrThrow("revisions",null,v);}
 public synchronized void revise(String p,long id,String text,String status){validate(text);if(!Arrays.asList("pendente","aprovado","retirado").contains(status))throw new IllegalArgumentException();SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{ContentValues v=new ContentValues();v.put("text",text.trim());v.put("status",status);v.put("updated",System.currentTimeMillis());if(d.update("knowledge",v,"profile=? AND id=?",new String[]{p,Long.toString(id)})!=1)throw new IllegalArgumentException("Registro inexistente");revision(p,id,text,status);d.setTransactionSuccessful();}finally{d.endTransaction();}}
 public synchronized JSONArray knowledge(String p){JSONArray result=new JSONArray();try(Cursor c=getReadableDatabase().rawQuery("SELECT id,question,text,status,created,updated FROM knowledge WHERE profile=? ORDER BY id DESC LIMIT 200",new String[]{p})){while(c.moveToNext())try{result.put(new JSONObject().put("id",c.getLong(0)).put("question",c.getString(1)).put("text",c.getString(2)).put("status",c.getString(3)).put("created",c.getLong(4)).put("updated",c.getLong(5)));}catch(JSONException e){throw new IllegalStateException(e);}}return result;}
 public String search(String p,String query){StringBuilder s=new StringBuilder();Set<String> terms=new HashSet<>(TextTools.tokens(query));if(terms.isEmpty())return "Digite um termo para buscar.";JSONArray rows=knowledge(p);for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(!"aprovado".equals(row.optString("status")))continue;Set<String> tokens=new HashSet<>(TextTools.tokens(row.optString("question")+" "+row.optString("text")));boolean hit=false;for(String word:terms)if(tokens.contains(word))hit=true;if(hit)s.append("#").append(row.optLong("id")).append(" • aprovado localmente • ").append(new java.util.Date(row.optLong("updated"))).append("\n").append(row.optString("text")).append("\n\n");}return s.length()==0?"Nenhuma explicação aprovada encontrada. Não vou inventar uma resposta.":s.toString();}
 public synchronized int claim(String p){SQLiteDatabase d=getWritableDatabase();String[] missions={"Primeira atividade sem ajuda","Primeira revisão posterior","Primeira explicação aprovada"};long[] checks={count("SELECT COUNT(*) FROM attempts WHERE profile=? AND assisted=0 AND correct=1",p),count("SELECT COUNT(*) FROM attempts WHERE profile=? AND reviewed=1",p),count("SELECT COUNT(*) FROM knowledge WHERE profile=? AND status='aprovado'",p)};for(int i=0;i<3;i++)if(checks[i]>0){ContentValues v=new ContentValues();v.put("profile",p);v.put("mission",missions[i]);v.put("xp",25);d.insertWithOnConflict("rewards",null,v,SQLiteDatabase.CONFLICT_IGNORE);}return (int)count("SELECT COALESCE(SUM(xp),0) FROM rewards WHERE profile=?",p);}
 public synchronized String report(String p){claim(p);StringBuilder s=new StringBuilder("Atividades sem ajuda: "+count("SELECT COUNT(*) FROM attempts WHERE profile=? AND assisted=0",p)+"; acertos: "+count("SELECT COUNT(*) FROM attempts WHERE profile=? AND assisted=0 AND correct=1",p)+"\nRevisões após 30 min: "+count("SELECT COUNT(*) FROM attempts WHERE profile=? AND reviewed=1",p)+"; acertos: "+count("SELECT COUNT(*) FROM attempts WHERE profile=? AND reviewed=1 AND review_correct=1",p)+"\nXP educativo: "+claim(p)+" (3 missões únicas de 25 XP)\n");try(Cursor c=getReadableDatabase().rawQuery("SELECT context,action,n,total FROM strategies WHERE profile=?",new String[]{p})){while(c.moveToNext())s.append(c.getString(0)).append(" / ").append(PedagogyPolicy.ACTIONS[c.getInt(1)]).append(": ").append(c.getInt(2)).append(" revisões, recompensa ").append(c.getDouble(3)).append("\n");}return s+"\nA taxa de acerto mede o desempenho do aluno; as recompensas ajustam a escolha de dicas do buddy. Repetir itens conhecidos não prova generalização.";}
 public JSONObject export(String p)throws JSONException{JSONObject root=new JSONObject().put("schema",1).put("profile",p).put("knowledge",knowledge(p));JSONArray attempts=new JSONArray();try(Cursor c=getReadableDatabase().rawQuery("SELECT * FROM attempts WHERE profile=? ORDER BY id",new String[]{p})){while(c.moveToNext()){JSONObject row=new JSONObject();for(int i=0;i<c.getColumnCount();i++)row.put(c.getColumnName(i),c.isNull(i)?JSONObject.NULL:c.getString(i));attempts.put(row);}}JSONArray revisions=new JSONArray();try(Cursor c=getReadableDatabase().rawQuery("SELECT * FROM revisions WHERE profile=? ORDER BY id",new String[]{p})){while(c.moveToNext()){JSONObject row=new JSONObject();for(int i=0;i<c.getColumnCount();i++)row.put(c.getColumnName(i),c.isNull(i)?JSONObject.NULL:c.getString(i));revisions.put(row);}}return root.put("attempts",attempts).put("revisions",revisions).put("report",report(p));}
}
